const wall = file.get(file.byType("IfcWall")[0]?.id ?? 1);
if (!wall) {
  throw new Error("No entity to inspect.");
}

console.log(wall.id, wall.type, wall.isA("IfcRoot"));
console.log("GlobalId:", wall.get("GlobalId"));
console.log("Attributes:", wall.attributes());
console.log("Inverse attrs:", wall.inverseAttributes());

const allWalls = file.all("IfcWall", { includeSubtypes: true });
console.log("Wall count:", allWalls.length);

// Do not call wall.dispose() / file.dispose() — file is owned by the inspection session.
